-action-modal-footer"><button type="button" class="btn btn-light" data-pe-dialog-close>Cancelar</button><button class="btn btn-primary" type="submit"><i class="bi bi-floppy"></i> Salvar frequência</button></footer></form></div></div></dialog>
<dialog class="pe-modal pe-modal--view" id="peAttendanceView"><div class="pe-modal__shell"><header class="pe-modal__header"><div><div class="card-kicker">Frequência</div><h2 data-pe-current-title>Detalhes</h2><p data-pe-current-subtitle></p></div><button type="button" class="pe-modal__close" data-pe-dialog-close><i class="bi bi-x-lg"></i></button></header><div class="pe-modal__body"><dl class="pe-modal-details pe-modal-details--3"><div><dt>Competência</dt><dd data-pe-text="competencia">—</dd></div><div><dt>Local</dt><dd data-pe-text="parceiro">—</dd></div><div><dt>Status</dt><dd data-pe-text="status">—</dd></div><div><dt>Dias previstos</dt><dd data-pe-text="dias_previstos">0</dd></div><div><dt>Presenças</dt><dd data-pe-text="presencas">0</dd></div><div><dt>Faltas</dt><dd data-pe-text="faltas">0</dd></div><div><dt>Percentual</dt><dd data-pe-text="percentual_formatado">—</dd></div><div><dt>Responsável</dt><dd data-pe-text="registrado_por">—</dd></div></dl><div class="pe-view-note"><strong>Observação</strong><p data-pe-text="observacao">—</p></div></div></div></dialog>
